mapper.select:
/** * selectRcivEqptIndtyMngList : isry.couns.mngr.atrzmng.mapper.RcivEqptIndtyMngMapper : 기자재수령확인서 목록조회 */ SELECT C##RG.DEC_B64(AA.RECEIV_NM_ENCPT) AS RECEIV_NM , AA.RECEIV_ID AS RECEIV_ID , SUBSTR(AA.RECPT_YMD, 1,4)||'-'||SUBSTR(AA.RECPT_YMD, 5,2)||'-'||SUBSTR(AA.RECPT_YMD, 7,2) AS RECPT_YMD , TO_CHAR(AA.FRST_REG_DT,'YYYY-MM-DD') AS REG_YMD , AA.INDEX_SN AS INDEX_SN , COUNT(*) OVER() AS TOTAL_COUNT FROM AYC330 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.DEL_YN = 'N' AND AA.RECEIV_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND CC.OGDP_DEPT_CD = #{deptCd}
AND AA.RECEIV_ID LIKE #{userId}||'%'
AND AA.RECEIV_NM_ENCPT = C##RG.ENC_B64(#{userNm})
ORDER BY AA.FRST_REG_DT DESC

/** * selectRcivEqptindtyMngDetail : isry.couns.mngr.atrzmng.mapper.RcivEqptIndtyMngMapper : 기자재수령확인서 상세조회 */ SELECT C##RG.DEC_B64(AA.RECEIV_NM_ENCPT) AS RECEIV_NM , AA.RECEIV_ID AS RECEIV_ID , DD.ENFSN_NO AS ENFSN_NO , TO_CHAR(AA.FRST_REG_DT,'YYYY-MM-DD') AS REG_YMD , AA.RECPT_YMD AS RECPT_YMD , AA.EQPMNT_SN AS EQPMNT_SN , BB.EQP_SE_CD AS EQP_SE_CD , AA.CHG_YMD AS CHG_YMD , AA.EQPMNT_ADDR AS EQPMNT_ADDR , AA.EQPMNT_DADDR AS EQPMNT_DADDR , AA.ZIP AS ZIP , AA.ATFINO AS ATFINO , AA.INDEX_SN AS INDEX_SN , C##RG.DEC_B64(DD.FLNM_ENCPT) AS FLNM_ENCPT , C##RG.DEC_B64(DD.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT , EE.STRG_COURS_NM || EE.STRG_FILE_NM AS FILE_INFO /* 사진 */ FROM AYC330 AA , ( SELECT LISTAGG(B1.RECPT_EQPMNT_SE_CD, ',') WITHIN GROUP (ORDER BY 1) AS EQP_SE_CD FROM AYC331 B1 WHERE 1=1
AND B1.RECPT_EQPMNT_CNFRMN_SN = #{indexSn}
) BB , SAA200 CC , SCA100 DD , (SELECT * FROM SAB821 WHERE ATCMFL_CL_NM = '서명사진' AND FILE_STTS_SE_CD = 'N' ) EE WHERE 1=1
AND AA.INDEX_SN = #{indexSn}
AND AA.RECEIV_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO AND AA.ATFINO = EE.ATFINO(+)

mapper.update:
/**
*		updateRcivEqptIndtyMng : isry.couns.mngr.atrzmng.mapper.RcivEqptIndtyMngMapper : 기자재수령확인서 수정
*/
	UPDATE
			AYC330		AA		/** 사이버1388 장비 **/
	SET
			AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE


		,	AA.EQPMNT_SN		=	#{eqpmntSn}		/**장비일련번호**/




		,	AA.CHG_YMD			=	#{chgYmd}		/**변경일자**/




		,	AA.RECPT_YMD		=	#{recptYmd}		/**수령일자**/




		,	AA.EQPMNT_ADDR		=	#{eqpmntAddr}




		,	AA.EQPMNT_DADDR		=	#{eqpmntDaddr}




		,	AA.ZIP	=	#{zip}




		,	AA.ATFINO	=	#{atfino}


	WHERE	1=1
		AND	AA.INDEX_SN			=	#{indexSn}
